      "content": "import { describe, expect, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { CompleteTask } from '../application/complete-task';

function setup() {
  const published: DomainEvent[] = [];
  const ctx: UseCaseContext = {
    correlationId: 'c1',
    causationId: 'k1',
    async publish(events) { published.push(...events); },
  };
  const repo = new InMemoryTaskRepository();
  return { published, ctx, repo, useCase: new CompleteTask(repo) };
}

describe('complete_task', () => {
  test(covers(['usecase:complete_task', 'criterion:0001/persistencia-conclusao'], 'salva completed, publica TaskCompleted e rejeita id ausente com TASK_NOT_FOUND'), async () => {
    const { published, ctx, repo, useCase } = setup();
    const task = Task.create('t1', 'Comprar pão');
    task.pullEvents();
    await repo.save(task);

    const out = await useCase.execute({ task_id: 't1' }, ctx);

    expect(out).toEqual({ task_id: 't1', status: 'completed' });
    expect((await repo.findById('t1'))!.status).toBe('completed');
    expect(published).toHaveLength(1);
    expect(published[0]).toBeInstanceOf(TaskCompleted);
    expect(published[0]!.payload).toEqual({ taskId: 't1' });

    let error: unknown;
    try {
      await useCase.execute({ task_id: 'missing' }, ctx);
    } catch (caught) {
      error = caught;
    }
    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_NOT_FOUND');
    expect(published).toHaveLength(1);
  });
});
